15:   const nodes = new Map();
16:   for (const node of graph.nodes) {
17:     if (!node || typeof node.id !== 'string' || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(node.id)
18:       || !nonempty(node.title) || !nonempty(node.reason)
19:       || !Array.isArray(node.evidence) || !node.evidence.length || !node.evidence.every(nonempty)
20:       || !Array.isArray(node.dependsOn) || !node.dependsOn.every(nonempty) || nodes.has(node.id)) {
21:       throw new Error('Each node needs a unique slug id, title, reason, evidence, and dependsOn array.');
22:     }
23:     // Outcomes are absent from a freshly planned graph and appended later by `tag record`.
24:     if (node.outcomes !== undefined && (!Array.isArray(node.outcomes) || !node.outcomes.length
25:       || !node.outcomes.every(item => item && nonempty(item.at) && nonempty(item.outcome)))) {
26:       throw new Error(`Node ${node.id} has outcomes that are not a nonempty list of {at, outcome}.`);
27:     }
28:     nodes.set(node.id, node);
29:   }
30:   const visiting = new Set();
31:   const visited = new Set();
32:   function visit(id) {
33:     if (!nodes.has(id)) throw new Error(`Unknown dependency: ${id}`);
34:     if (visiting.has(id)) throw new Error(`Dependency cycle: ${id}`);
35:     if (visited.has(id)) return;
36:     visiting.add(id);
37:     for (const dependency of nodes.get(id).dependsOn) visit(dependency);
38:     visiting.delete(id);
39:     visited.add(id);
