102:       { role: 'system', content: instructions },
103:       { role: 'user', content: objective },
104:     ];
105:     attempt.priorGraph = prior ? graphPath : null;
106:     let supplied = false;
107:     const investigation = attempt.investigation;
108:     const researched = () => investigation.some(item => item.tool === 'read_file' && /^\d+: /.test(item.result));
109:     for (let turn = 1; turn <= MAX_REQUESTS; turn++) {
110:       attempt.requests = turn;
111:       // Supplied with the graph up front, a real run answered with the graph: it restated three
112:       // of its four nodes verbatim, read nothing, and cited files it had never opened. The
113:       // durable state is real input, so it is withheld until the repository has actually been
114:       // investigated, and never allowed to stand in for investigating it.
115:       if (prior && !supplied && researched()) {
116:         supplied = true;
117:         messages.push({ role: 'user', content: `Now that you have investigated, here is the durable graph for this objective, including outcomes recorded by a human after work was actually performed:\n${JSON.stringify(prior, null, 2)}` });
118:       }
119:       const body = {
120:         model: MODEL, messages, tools, max_tokens: MAX_OUTPUT,
121:         tool_choice: turn === MAX_REQUESTS ? 'none' : 'auto',
122:         temperature: 0.2,
123:         provider: { max_price: { prompt: 0.5, completion: 1.5 } },
124:       };
125:       if (Buffer.byteLength(JSON.stringify(body)) > MAX_CONTEXT_BYTES) {
126:         throw new Error('Research context limit reached. No graph saved; human review required.');
127:       }
128:       const response = await request('/chat/completions', {
129:         method: 'POST',
130:         headers: { Authorization: 'Bearer ' + apiKey, 'Content-Type': 'application/json' },
131:         body: JSON.stringify(body),
132:       }, fetchImpl);
133:       const cost = response.usage?.cost;
134:       attempt.costUsd = attempt.costUsd !== null && typeof cost === 'number' && Number.isFinite(cost) && cost >= 0
135:         ? attempt.costUsd + cost : null;
136:       const choice = response.choices?.[0];
137:       const message = choice?.message;
138:       if (!message || choice.finish_reason === 'length' || response.error) {
139:         throw new Error('The model returned an error or incomplete answer. No retry was made.');
140:       }
141:       if (message.tool_calls?.length) {
142:         if (turn === MAX_REQUESTS || message.tool_calls.length > 12) throw new Error('Investigation limit reached.');
143:         messages.push({ role: 'assistant', content: message.content ?? null, tool_calls: message.tool_calls });
144:         for (const call of message.tool_calls) {
145:           let args;
146:           let result;
147:           try {
148:             args = JSON.parse(call.function.arguments);
149:             result = await investigate(call.function.name, args);
150:           } catch {
151:             // Do not return raw filesystem errors or other environment details to the model.
152:             result = 'Tool unavailable or invalid arguments. Use listed tracked text files and the documented tool parameters.';
153:           }
154:           investigation.push({ tool: call.function.name, arguments: args ?? {}, result });
155:           messages.push({ role: 'tool', tool_call_id: call.id, content: result });
156:         }
157:         continue;
158:       }
159:       // Keep the answer before anything can reject it. A run that answered without investigating
160:       // at all was rejected here and its answer was lost, which is the failure failed-run.json
161:       // exists to prevent; the preservation path only triggered once this had already been set.
162:       attempt.answer = message.content;
163:       if (!researched()) {
164:         throw new Error('The model proposed a graph without reading repository evidence.');
165:       }
166:       // A complete, otherwise valid graph was once discarded because the model wrapped it in a
167:       // markdown fence. Removing that envelope is not JSON repair: malformed JSON inside it,
168:       // a drifted objective or an invalid graph are still rejected exactly as before.
169:       const fenced = message.content.trim().match(/^```[a-z]*\s*\n([\s\S]*?)\n?```$/i);
