175:       }
176:       graph.run = { model: MODEL, createdAt: attempt.createdAt, requests: turn, costUsd: attempt.costUsd, priorGraph: attempt.priorGraph, investigation };
177:       const html = renderGraph(graph);
178:       keep = true;
179:       await writeFile(join(output, 'graph.json'), JSON.stringify(graph, null, 2) + '\n', { flag: 'wx', mode: 0o600 });
180:       await writeFile(join(output, 'graph.html'), html, { flag: 'wx', mode: 0o600 });
181:       return join(output, 'graph.html');
